import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"26、【大畜】 乾下艮上","description":"周易集註 - 26、【大畜】 乾下艮上","frontmatter":{"title":"26、【大畜】 乾下艮上","description":"周易集註 - 26、【大畜】 乾下艮上"},"headers":[],"relativePath":"classics/jizhu/030.md","filePath":"classics/jizhu/030.md"}'),l={name:"classics/jizhu/030.md"};function t(h,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_26、【大畜】-乾下艮上" tabindex="-1">26、【大畜】 乾下艮上 <a class="header-anchor" href="#_26、【大畜】-乾下艮上" aria-label="Permalink to “26、【大畜】 乾下艮上”">​</a></h1><p>大者陽也，其卦幹下艮上，以陽畜陽，所以畜之力大，非如巽以陰畜陽，所畜之力小，故曰大畜。又有蘊畜之義，又有畜止之義。《序卦》：“有無妄，然後可畜，故受之以大畜，所以次無妄。”</p><p>中爻兌口在外，四近於五之君，當食祿於朝，不家食之象也。何以言食?本卦大象離，故《彖》辭曰“輝光日新”者，因大象離也。離錯坎，又象頤，有飲食自養之象。因錯坎水，中爻震木，所以有涉大川之象。又本卦錯萃，萃大象坎。若以卦體論，四五中空，有舟象。乾健應四五上進，有舟行而前之象。應乎天者，以卦德論其理也，彖辭爻辭皆各取義不同。貞者正也，利於正道，如多識前言往行，以畜其德是也。吉者，吾道之大行也。言所蘊畜者皆正，則畜極而通，當食祿於朝，大有作為，以濟天下之險也。</p><p>《彖》曰：大畜，剛健篤實，輝光日新其德，剛上而尚賢。能止健，大正也。不家食吉，養賢也。利涉大川，應乎天也。</p><p>以卦德、卦綜、卦體釋卦名、卦辭。剛健者，內而存主也。篤實者，外而踐履也。剛健無一毫人慾之陰私，篤實無一毫人慾之虛假，則闇然日章，光輝宣著，其德自日新又新，所以積小高大，以成其畜也。名大畜者以此。剛健乾象，篤實艮象，二體相合離象，故又言輝光日新。剛上者，大畜綜無妄，無妄下卦之震上而為大畜之艮也，上而為艮，則陽剛之賢在上矣，是尚其賢也。止健者，止居上，而健居下，禁民之強暴也，此二者，皆大正之事，所以利貞，若以止健為止陽剛君子，則又非大正矣。養賢者，食祿以養賢也。應天者，下應乎幹也。天者時而已矣，既負蘊畜之才，又有乾健之力，所以當乘時而出，以濟天下之險難也。惟剛上，則賢人在上，故能尚賢，故能成艮而止健，故能兌口在外卦，而食祿於外。故能六五得中，而應乎幹。此四者，皆卦綜剛上之功也。</p><h3 id="《象》曰-天在山中-大畜-君子以多識前言往行-以畜其德。" tabindex="-1">《象》曰：天在山中，大畜，君子以多識前言往行，以畜其德。 <a class="header-anchor" href="#《象》曰-天在山中-大畜-君子以多識前言往行-以畜其德。" aria-label="Permalink to “《象》曰：天在山中，大畜，君子以多識前言往行，以畜其德。”">​</a></h3><p>天者一氣而已，氣貫乎地中，天依乎地，地附乎天，雲雷皆自地出。故凡地下空處、深處皆是天，故曰天在山中。多識，即大畜之意，乃知之功夫也。古聖賢之嘉言善行，皆理之所在，皆古人之德也。君子多識之，考跡以觀其用，察言以求其心，則萬理會通於我，而我之德大矣，此君子體大畜之功也。中爻震，足行之象。兌口，言之象。</p><p>初九，有厲，利已。(已，夷止反。)</p><p>幹三陽為艮所畜，故內外之卦，各具其義。內卦受畜，以自止為義。以陰陽論，若君子受畜於小人也。外卦能畜，以止人為義。以上下論，若在位之禁止強暴也。易主於變易，所以取義不窮。已者止也。厲者不相援，而反相擠排，危厲之道也。</p><p>初九陽剛乾體，志於必進。然當大畜之時，為六四所畜止，而不得自伸，故往則有危。惟止則不取禍矣，故教佔者必利於止也。</p><h3 id="《象》曰-有厲利已-不犯災也。" tabindex="-1">《象》曰：有厲利已，不犯災也。 <a class="header-anchor" href="#《象》曰-有厲利已-不犯災也。" aria-label="Permalink to “《象》曰：有厲利已，不犯災也。”">​</a></h3><p>災即厲也，止而不行，則不犯災矣。</p><p>九二，輿說輹。(說音脫，輹音服。)</p><p>幹錯坤為輿，輿之象也。中爻兌為毀折，脫輹之象也。輿賴輹以行，脫則止而不行矣。</p><p>九二亦為六五所畜，以有中德，能自止而不進，故有輿說輹之象。佔者凡事不冒進，斯無尤。</p><h3 id="《象》曰-輿說輹-中無尤也。" tabindex="-1">《象》曰：輿說輹，中無尤也。 <a class="header-anchor" href="#《象》曰-輿說輹-中無尤也。" aria-label="Permalink to “《象》曰：輿說輹，中無尤也。”">​</a></h3><p>惟有中德，故無妄進之尤。</p><p>九三，良馬逐，利艱貞，曰閒輿衛，利有攸往。</p><p>此爻取蘊蓄之義。幹為良馬，之象之象也。中爻震，為作足之馬，乾馬在後追逐震馬之象也。兩馬因震動而追逐，遇艮止不得馳上，利艱貞之象也。中爻兌口，幹為言，曰之象也。幹錯坤，輿之象也。陰爻兩列在前，衛之象也。《考工記》：“車有六等，戈也、人也、殳也、戟也、矛也、軫也，皆衛名。”良馬逐者，用功如良馬追逐之速也，即九三終日乾乾夕惕若之意。艱者，艱難其思慮，恐其失於太易也。貞者，貞固其作為，恐其失於助長也。曰者自嘆之辭。閒者習也，習其車輿與其防衛也。閒習有優遊自得之意。曰閒輿衛者，自嘆其當閒與衛也，言當此大畜之時，為人所畜止摧抑，果何所事哉!亦惟自閒輿衛，以求往乎天衢耳。輿者任重之物，衛者應變之物。以人事論，君子不當家食，以一身而任天下之重者，輿也;當涉大川，以一身而應天下之變者，衛也。必多識前言往行之理，畜其剛健篤實之德，以德為車，以樂為御，忠信以為甲冑，仁義以為幹櫓，涵養於未用之時，以待時而動，此閒輿衛之意也。閒輿衛又利艱貞之象也，舊注以不相畜而俱進，殊不知卦名大畜，下體非自止，則蘊畜也，無進之意。蓋觀童牛之牿則知當有厲利已矣，觀豶豕之牙則知當輿說輹矣，觀何天之衢則知用功當良馬逐矣。所以小象言上合志，所以當取蘊畜之義。唯蘊畜，方能畜極而通，何天之衢。</p><p>九三以陽居健極，當大畜之時，正多識前言往行，用功不已之時也，故有良馬追逐之象。然猶恐其過剛銳進，惟當艱貞，從容以待時，故又有曰閒輿衛之象。如是自然畜極而通，利有攸往矣。故教戒佔者，必當如此。</p><h3 id="《象》曰-利有攸往-上合志也。" tabindex="-1">《象》曰：利有攸往，上合志也。 <a class="header-anchor" href="#《象》曰-利有攸往-上合志也。" aria-label="Permalink to “《象》曰：利有攸往，上合志也。”">​</a></h3><p>上合志者，謂上九之志與之相合也，三與上九，情雖不相孚，然皆居二體之上，其志皆欲畜極而通，應與相合，所以利有攸往。</p><p>六四，童牛之梏*，元吉。</p><p>童者，未角之稱。梏者施橫木於牛角，以防其觸，即《詩》所謂“楅衡”者也。此爻變離，離為牛，牛之象也。艮本少又應初，童牛之象也。變離錯坎，梏之象也。艮手，中爻震木，手持木而施之角，亦梏之象也。</p><p>六四艮體居上，當畜幹之時，與初相應，畜初者也。初以陽剛居卦之下，其勢甚微，於此止之，為力甚易，故有梏童牛之象。佔者如此，則止惡於未形，用力少而成功多，大善而吉之道也，故元吉。</p><ul><li>案：“梏”應作“牿”。</li></ul><h3 id="《象》曰-六四元吉-有喜也。" tabindex="-1">《象》曰：六四元吉，有喜也。 <a class="header-anchor" href="#《象》曰-六四元吉-有喜也。" aria-label="Permalink to “《象》曰：六四元吉，有喜也。”">​</a></h3><p>上不勞于禁制，下不傷於刑誅，故可喜。四正當兌口之悅，喜之象也。</p><p>六五，豶豕之牙，吉。(豶音焚)</p><p>本卦大象離，離錯坎，豕之象也。五變中爻又成離矣。豶者犗也，騰也，乃走豕也，與童牛之梏一句同例。童字與豶字同，梏字與牙字同。中爻震足性動，豶之象也。牙者，《埤雅》雲“以杙系豕也”，乃杙牙非齒牙也。《杜詩》“鳧雛入槳牙”，《坡詩》“置酒看君中戟牙”，荊公“槎牙死樹鳴老烏”，《阿房賦》“簷牙高啄”，又將軍之旗曰牙，立於帳前，謂之牙帳。《考工記‧輪人》“牙也者所以為固抱也”，所以蜀人呼棹牙、凳牙、床牙，則牙字古今通用，非齒牙也。《詩》“椓之丁丁”，丁丁杙聲也，以木入土，所以有聲也。今船家系纜樁謂之燦，亦曰杙，牙者樁上權牙也。蓋以絲系矢曰弋，故從弋，所以繩系木曰杙。變巽為繩，系之象也。巽木，杙之象也。言以繩系走豕於杙牙也。舊注，因宮刑或犗刑，遂以為去其勢，但天下無齧人之豕，所以此豶字止有騰字意，無犗字意，牛馬豕皆人之畜者，故大畜並言之。</p><p>六五以柔中居尊位，當畜幹之時，畜乎其二者也，故有豶豕之牙之象，佔者如此，則強暴梗化者，自屈服矣，故言。</p><h3 id="《象》曰-六五之吉-有慶也。" tabindex="-1">《象》曰：六五之吉，有慶也。 <a class="header-anchor" href="#《象》曰-六五之吉-有慶也。" aria-label="Permalink to “《象》曰：六五之吉，有慶也。”">​</a></h3><p>慶即喜，但五君位，所畜者大，故曰慶，即一人有慶也。</p><p>上九，何天之衢，亨。</p><p>此畜極而通之義。何，胡可切，音荷，儋也，負也。儋即擔字，楊子儋石是也。《詩》“何蓑何笠”，皆音荷，《靈光賦》“荷天衢以元亨”，《莊子》“揹負青天”，皆此意。鄭康成亦言“肩荷”是也。上陽一畫象擔，二陰垂嚲於兩邊，有擔挑之象，言一擔挑起天衢也，即陳白沙所謂“明月清風作兩頭，一挑挑到魯尼丘”也。因卦體取此象，無此實事，金車玉鉉之類是也。上為天位，天之象也。四達謂之衢，艮綜震為大塗，衢之象也。以人事論，天衢乃朝廷政事之大道也。觀《小象》曰“道大行”可知矣。</p><p>畜之既久，其道大行。正不家食，擔任廟廊之重任。涉大川，擔當國家之險阻，此其時矣，故有何天衢之象。佔者得此，亨可知矣。</p><h3 id="《象》曰-何天之衢-道大行也。" tabindex="-1">《象》曰：何天之衢，道大行也。 <a class="header-anchor" href="#《象》曰-何天之衢-道大行也。" aria-label="Permalink to “《象》曰：何天之衢，道大行也。”">​</a></h3><p>道大行者，不家食，涉大川，無往而莫非亨也。道字即衢字。</p>',38)])])}const f=e(l,[["render",t]]);export{_ as __pageData,f as default};
